import { useState, useEffect, useLayoutEffect } from 'react';

function SearchResults({ query }) {
  const [results, setResults] = useState([]);

  // Render phase: pure calculation only
  const visibleResults = results.filter((item) =>
    item.title.toLowerCase().includes(query.toLowerCase())
  );

  // Commit phase: side effects after DOM is updated
  useEffect(() => {
    document.title = `${visibleResults.length} results for "${query}"`;
    analytics.track('search', { query, count: visibleResults.length });
  }, [query, visibleResults.length]);

  return (
    <ul>
      {visibleResults.map((item) => (
        <li key={item.id}>{item.title}</li>
      ))}
    </ul>
  );
}
